fn path(header: &[u8]) -> Result<String> {
    let end = header[..100]
        .iter()
        .position(|byte| *byte == 0)
        .unwrap_or(100);
    let path = std::str::from_utf8(&header[..end]).context("bounded TAR path must be UTF-8")?;
    let components = path.split('/').collect::<Vec<_>>();
    let valid = !path.is_empty()
        && path.len() <= 256
        && !path.contains('\\')
        && components.len() <= 12
        && components.iter().all(|component| {
            !component.is_empty()
                && *component != "."
                && *component != ".."
                && component.len() <= 96
                && component.bytes().all(|byte| {
                    byte.is_ascii_alphanumeric()
                        || matches!(byte, b'.' | b'_' | b'-' | b'[' | b']' | b'@')
                })
        });
    if !valid {
        bail!("bounded TAR path must be a bounded relative file path");
