fn octal(bytes: &[u8], label: &str) -> Result<usize> {
    let trimmed = bytes
        .iter()
        .copied()
        .skip_while(|byte| matches!(byte, 0 | b' '))
        .take_while(|byte| !matches!(byte, 0 | b' '))
        .collect::<Vec<_>>();
    if trimmed.is_empty() || trimmed.iter().any(|byte| !matches!(byte, b'0'..=b'7')) {
        bail!("bounded TAR {label} is not canonical octal");
    }
    trimmed.iter().try_fold(0usize, |value, byte| {
        value
            .checked_mul(8)
            .and_then(|value| value.checked_add(usize::from(*byte - b'0')))
            .context("bounded TAR octal value overflow")
    })
}

fn slice(bytes: &[u8], start: usize, end: usize) -> Result<&[u8]> {
    bytes
        .get(start..end)
        .context("bounded TAR entry is truncated")
}

